select count(distinct m.id)
from members m
join registrations r on r.user_id = m.user_id and r.status = 1
join activities a on a.id = r.activity_id
where m.club_id = #{clubId}
  and m.status = 1
  and a.club_id = #{clubId}
  and r.registration_time >= #{since}

